def make(n):
    # build a SpecifierSet string with n simple specs
    specs = []
    for i in range(1, n+1):
        specs.append(f">=1.{i}.0")
    return [[",".join(specs), "1.5.0"]]

def make(n):
    specs = [f">=1.{i}.0" for i in range(1, n+1)]
    return [[",".join(specs), "1.5.0+local"]]

def make(n):
    specs = [f"<={i}.0" for i in range(1, n + 1)]
    return [[", ".join(specs), "2.5"]]

def make(n):
    specs = []
    for i in range(1, n // 2 + 1):
        specs.append(f">={i}.0")
        specs.append(f"<={(i * 2)}.0")
    if len(specs) < n:
        specs.extend([f">={len(specs)+j}.0" for j in range(1, n - len(specs) + 1)])
    return [["," .join(specs[:n]), "1.0"]]
